import{_ as a,H as e,f as t,i as r}from"./chunks/framework.Cvt1eIE0.js";const I=JSON.parse('{"title":"PIGLIN KING 第三巻 エンダードラゴン戦争","description":"","frontmatter":{"title":"PIGLIN KING 第三巻 エンダードラゴン戦争","outline":"deep"},"headers":[],"relativePath":"story/3-1.md","filePath":"story/3-1.md"}'),o={name:"story/3-1.md"};function i(n,p,l,h,s,d){return e(),t("div",null,[...p[0]||(p[0]=[r('<h1 id="piglin-king" tabindex="-1">PIGLIN KING <a class="header-anchor" href="#piglin-king" aria-label="Permalink to &quot;PIGLIN KING&quot;">​</a></h1><h2 id="第三巻-エンダードラゴン戦争" tabindex="-1">第三巻 エンダードラゴン戦争 <a class="header-anchor" href="#第三巻-エンダードラゴン戦争" aria-label="Permalink to &quot;第三巻 エンダードラゴン戦争&quot;">​</a></h2><hr><h1 id="第一章-共闘" tabindex="-1">第一章 共闘 <a class="header-anchor" href="#第一章-共闘" aria-label="Permalink to &quot;第一章 共闘&quot;">​</a></h1><p>崩れゆく黒曜石の宮殿。</p><p>天井が裂け、紫色の光が瓦礫の隙間から漏れていた。</p><p>巨大な翼が、その光を遮るように広がっていた。</p><p>紫色の瞳。</p><p>世界を揺るがす咆哮。</p><p>ゴォォォォォ！！</p><p>「エンダードラゴン……。」</p><p>スターリンですら、後ずさった。あの男が後ずさる。それだけで、この敵がどれほどの存在か、誰の目にも分かった。</p><p>崩れた瓦礫の中。</p><p>エンド帝国皇帝。</p><p>ENDER EMPEROR。</p><p>彼は、ゆっくりと立ち上がった。先ほどまで黄金王と剣を交えていたその手が、今は静かに剣を下ろしていた。</p><p>「黄金王。」</p><p>「どうやら。」</p><p>「我々は同じ敵を前にしているらしい。」</p><p>オーレックスは微笑んだ。疲労の中に、それでも確かな光があった。</p><p>「最初からそう言ってる。」</p><p>「一緒に戦おう。」</p><p>数千年の間、争い続けてきた二つの国。</p><p>PIGLIN KINGDOM。</p><p>そしてエンド帝国。</p><p>互いを敵と呼び、互いを恐れ、互いの存在を伝説と昔話の中に押し込めてきた、二つの歴史。</p><p>その歴史上、初めて。</p><p>両国は、同盟を結ぶことになった。</p><p>竜の咆哮が、それを祝うように――いや、それを嘲笑うように、もう一度響いた。</p><hr><h1 id="第二章-竜王" tabindex="-1">第二章 竜王 <a class="header-anchor" href="#第二章-竜王" aria-label="Permalink to &quot;第二章 竜王&quot;">​</a></h1><p>ゴォォォォ！！</p><p>エンダードラゴンは、再び咆哮した。</p><p>その瞬間。</p><p>宮殿の至るところで、エンダーマンたちの目が、一斉に紫色に染まった。</p><p>「まずい！」</p><p>ピックバーグは叫んだ。眼鏡の奥の目が、見開かれていた。</p><p>「精神支配だ！」</p><p>「ドラゴンが、エンドの民を操ってる！」</p><p>理性を失った民が、剣を抜き、互いを、そして味方であるはずの兵士たちを、襲い始めた。</p><p>「つまり！」</p><p>スターリンが斧を構える。その目には、いつもの豪快さの奥に、わずかな苦さがあった。</p><p>「全部助けなきゃならねぇってことか！」</p><p>「そういうこと！」</p><p>それは、これから始まる戦いが、ただの戦争ではないことを意味していた。</p><p>敵を倒すだけでは、終わらない。</p><p>敵にされた者たちを、救わなければならない。</p><hr><h1 id="第三章-世界連合軍" tabindex="-1">第三章 世界連合軍 <a class="header-anchor" href="#第三章-世界連合軍" aria-label="Permalink to &quot;第三章 世界連合軍&quot;">​</a></h1><p>王国歴十三年。</p><p>一年の時が流れた。</p><p>その一年は、軍を集めるための一年であり、傷を癒すための一年であり、そして、覚悟を固めるための一年だった。</p><p>PIGLIN KINGDOM。</p><p>エンド帝国。</p><p>百部族同盟。</p><p>かつて互いに無関心だった、あるいは敵だった勢力が、玄武岩デルタの大平原に、一つの旗の下に集結した。</p><p>王立陸軍。</p><p>王立海軍。</p><p>親衛軍。</p><p>エンド帝国第一軍団。</p><p>皇帝親衛軍。</p><p>それぞれの旗が、風もないはずの戦場で、不思議とはためいているように見えた。</p><p>総兵力。</p><p>二百万。</p><p>史上最大の軍勢が、地平線を埋め尽くしていた。</p><p>「行くぞ！」</p><p>スターリンの声が、戦場全土に響いた。</p><p>「おおおお！！」</p><p>歓声が、地響きのように広がった。</p><p>そして。</p><p>最前列。</p><p>黄金王。</p><p>KING PIGLIN I。</p><p>エンド帝国皇帝。</p><p>ENDER EMPEROR。</p><p>数千年敵対していた二人の王が、初めて並び立った。</p><p>その光景を、誰もが息を呑んで見つめていた。</p><p>「世界を守る。」</p><p>「必ず。」</p><p>短い言葉だった。だが、その奥には、数千年分の歴史と、数百万の命の重さが、確かに込められていた。</p><p>こうして。</p><p>エンダードラゴン戦争が、始まった。</p><hr><h1 id="第四章-最初の敗北" tabindex="-1">第四章 最初の敗北 <a class="header-anchor" href="#第四章-最初の敗北" aria-label="Permalink to &quot;第四章 最初の敗北&quot;">​</a></h1><p>しかし。</p><p>現実は、甘くなかった。</p><p>ドォォォォン！！</p><p>ブレス一撃。</p><p>それだけで、目の前の山が、跡形もなく消し飛んだ。</p><p>「うそだろ……。」</p><p>スターリンの顔から、血の気が引いた。歴戦の戦士である彼が、初めて見せた、本物の恐怖だった。</p><p>一撃。</p><p>ただの一撃で、一万人の兵が消えた。</p><p>さらに。</p><p>ドラゴンの咆哮。</p><p>ゴォォォ！！</p><p>その音だけで、兵士たちの心は折れた。</p><p>「ぐわぁ！」</p><p>次々と倒れていく。剣を抜くことすら、できなかった。</p><p>「近付くことすらできない！」</p><p>元帥が、絶叫した。</p><p>数で押すという、これまでのどんな戦いでも有効だった戦術が、ここでは、何の意味も持たなかった。</p><p>初戦。</p><p>世界連合軍は、敗北した。</p><p>撤退の角笛が、戦場に鳴り響いた。</p><p>そして。</p><p>誰も、まだ知らなかった。</p><p>これが、絶望の始まりに過ぎないことを。</p>',108)])])}const _=a(o,[["render",i]]);export{I as __pageData,_ as default};
